  <?php endforeach ?>
</div>
<?php }

/* ================================================================ styles, scripts, logos */
function asset_files(): array {
    return [
        'css/site.css' => ['text/css', <<<'__TMR_ASSET_0__'
/* Toramori storefront â€” clean white, black and tiger orange */
:root{
  /* Toramori: clean white pages, black type, tiger orange for actions */
  --surface:#FFFFFF;--raised:#F8F6F2;--sunken:#F2EFE9;--line:#E7E2D9;--line-strong:#CBC3B5;
  --ink:#141210;--muted:#6A6258;
  --shu:#E8681A;--shu-soft:#FDEBDD;--on-shu:#141210;
  --ai:#B9480B;--ai-soft:#FCEFE4;--kin:#B9480B;--kin-soft:#FCEFE4;
  --matcha:#2F7D46;--matcha-soft:#E6F3EA;--danger:#C2341B;--danger-soft:#FBE6E1;
  --gold-grad:linear-gradient(180deg,#F27A2C 0%,#E2600F 100%);
  --display:"Archivo","Zen Kaku Gothic New","Helvetica Neue",Arial,sans-serif;
  --sans:"Zen Kaku Gothic New","Hiragino Sans","Yu Gothic",system-ui,sans-serif;
  --mono:"IBM Plex Mono",ui-monospace,"SF Mono",Menlo,monospace;
  --container:1312px;--gutter:24px;--hdr:72px;
  --focus:0 0 0 2px #FFFFFF,0 0 0 4px #E8681A;
}
*{box-sizing:border-box}
[hidden]{display:none!important}
html{-webkit-text-size-adjust:100%;scroll-padding-top:120px}
body{margin:0;background:var(--surface);color:var(--ink);font:16px/26px var(--sans);-webkit-font-smoothing:antialiased;overflow-x:hidden}
img{max-width:100%;height:auto}
a{color:var(--ai);text-decoration:none}a:hover{color:#8F3807}
:focus-visible{outline:2px solid transparent;box-shadow:var(--focus)}
button,input,select,textarea{font:inherit;color:inherit}
.sr{position:absolute!important;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.skip{position:absolute;left:-999px;top:8px;background:var(--shu);color:var(--on-shu);padding:8px 12px;z-index:100}.skip:focus{left:8px}
.wrap{max-width:var(--container);margin:0 auto;padding:0 16px}
@media(min-width:1344px){.wrap{padding:0}}
.mono{font-family:var(--sans);font-variant-numeric:tabular-nums}.mincho{font-family:var(--display);font-weight:600}
.muted{color:var(--muted)}.small{font-size:13px;line-height:20px}.center{text-align:center}
.shu{color:var(--shu)}.ai{color:var(--ai)}.gold{color:var(--kin)}.matcha{color:var(--matcha)}
.flex1{flex:1}.row-between{display:flex;justify-content:space-between;align-items:baseline;gap:12px}
.row-gap{display:flex;gap:8px;flex-wrap:wrap}
.eyebrow{font-size:12px;line-height:16px;letter-spacing:.12em;font-weight:500;text-transform:uppercase;color:var(--muted)}
.display{font-family:var(--display);font-weight:600;font-size:clamp(40px,5vw,68px);line-height:1.05;letter-spacing:-.01em;margin:0;max-width:15ch}
.h1{font-family:var(--display);font-weight:600;font-size:clamp(30px,3.4vw,44px);line-height:1.15;margin:8px 0 16px}
.h2{font-family:var(--display);font-weight:600;font-size:clamp(24px,2.6vw,34px);line-height:1.25;margin:4px 0}
.h2.big{font-size:clamp(28px,3vw,40px)}
.h3{font-family:var(--display);font-weight:600;font-size:20px;line-height:28px;margin:0 0 12px}
.lead{font-size:18px;line-height:30px;max-width:60ch}
.section{padding-top:88px}.section-sm{padding-top:40px}
.sec-head{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:flex-end;gap:12px 24px;margin-bottom:28px}
.sec-head a{font-size:14px;font-weight:500}

/* buttons, tags, inputs */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;height:44px;padding:0 20px;border:1px solid var(--line-strong);border-radius:2px;background:transparent;color:var(--ink);font-size:14px;font-weight:500;cursor:pointer;text-decoration:none;white-space:nowrap}
.btn:hover{background:var(--sunken);color:var(--ink)}
.btn-primary{background:var(--gold-grad);border-color:#C9560F;color:var(--on-shu);font-weight:700}.btn-primary:hover{background:var(--gold-grad);color:var(--on-shu);filter:brightness(1.08)}
.btn-quiet{border-color:transparent;text-decoration:underline;text-underline-offset:4px}
.btn-sm{height:36px;padding:0 14px}.btn-lg{height:52px;padding:0 28px;font-size:15px}.btn-block{width:100%}
.btn[disabled]{opacity:.5;cursor:not-allowed}
.btns{display:flex;flex-wrap:wrap;gap:12px}
.tag{display:inline-flex;align-items:center;gap:6px;font-size:11px;line-height:16px;font-weight:500;letter-spacing:.08em;text-transform:uppercase;padding:3px 8px;border-radius:2px;background:var(--sunken);color:var(--muted)}
.tag:before{content:"";width:6px;height:6px;background:currentColor}
.tag-stock{background:var(--matcha-soft);color:var(--matcha)}.tag-preorder{background:var(--ai-soft);color:var(--ai)}.tag-limited{background:var(--kin-soft);color:var(--kin)}
.input{width:100%;height:44px;padding:0 12px;background:var(--raised);border:1px solid var(--line-strong);border-radius:2px;color:var(--ink)}
textarea.input{height:auto;padding:10px 12px;line-height:22px}
select.input{appearance:auto}
.lattice{background-color:var(--sunken);background-image:linear-gradient(45deg,transparent calc(50% - .5px),var(--line) calc(50% - .5px),var(--line) calc(50% + .5px),transparent calc(50% + .5px)),linear-gradient(-45deg,transparent calc(50% - .5px),var(--line) calc(50% - .5px),var(--line) calc(50% + .5px),transparent calc(50% + .5px));background-size:32px 32px}
.panel-box{background:var(--raised);border:1px solid var(--line);border-radius:4px;padding:24px;margin:0 0 24px;min-width:0}
fieldset.panel-box legend{float:left;width:100%;padding:0}
.note-ai{background:var(--ai-soft);color:var(--ai);padding:10px 14px;border-radius:2px;margin:12px 0}
.alert{background:var(--danger-soft);color:var(--danger);padding:12px 16px;border-radius:2px;margin-bottom:24px}
.err{display:block;color:var(--danger);font-size:13px}

/* announcement + header */
.bar{background:var(--raised);border-bottom:1px solid var(--line);font-size:13px;line-height:20px;color:var(--muted)}
.bar-in{display:flex;flex-wrap:wrap;justify-content:space-between;gap:4px 24px;padding-top:8px;padding-bottom:8px}.bar a{color:var(--kin)}
.hdr{position:sticky;top:0;z-index:40;background:var(--surface);border-bottom:1px solid var(--line)}
.hdr-in{height:var(--hdr);display:flex;align-items:center;gap:24px}
.logo{display:flex;color:var(--ink);flex:none}
.nav{display:flex;align-items:stretch;height:var(--hdr);flex:1;min-width:0}
.nav-btn{height:var(--hdr);display:inline-flex;align-items:center;gap:6px;padding:0 12px;border:0;background:none;color:var(--muted);font-size:15px;font-weight:500;cursor:pointer;white-space:nowrap}
.nav-item:hover .nav-btn,.nav-btn[aria-expanded="true"]{color:var(--ink);box-shadow:inset 0 -2px 0 var(--shu)}
.panel{position:absolute;left:0;right:0;top:100%;background:var(--raised);border-bottom:1px solid var(--line);box-shadow:0 16px 40px -12px #1412101F}
.panel-grid{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:24px;padding-top:32px;padding-bottom:36px}
.pcol .eyebrow{padding-bottom:12px;margin-bottom:6px;border-bottom:1px solid var(--line)}
.pcol ul{list-style:none;margin:0;padding:0}
.pcol a{display:flex;align-items:baseline;gap:10px;padding:6px 0;color:var(--ink);font-size:15px;line-height:22px}.pcol a:hover{color:var(--shu)}
.pcol .code{font-family:var(--sans);font-variant-numeric:tabular-nums;font-size:12px;color:var(--muted);min-width:30px}.pcol .code:empty{min-width:0}
.pcol .note{font-size:11px;letter-spacing:.08em;color:var(--ai)}
.feature{grid-column:span 4;display:flex;flex-direction:column;justify-content:flex-end;gap:8px;min-height:220px;padding:24px;border:1px solid var(--line);color:var(--ink)}
.feature strong{font-family:var(--display);font-size:24px;line-height:30px}.feature .tag{align-self:flex-start}
.feature:hover{color:var(--ink)}.feature:hover .shu{text-decoration:underline}
.hdr-tools{display:flex;align-items:center;gap:8px;flex:none}
.search{position:relative}.search input{width:220px;height:44px;padding:0 12px;background:var(--surface);border:1px solid var(--line);border-radius:2px;color:var(--ink)}
.instant{position:absolute;right:0;top:48px;width:min(440px,92vw);background:var(--raised);border:1px solid var(--line);box-shadow:0 16px 40px -12px #1412101F;z-index:60;max-height:70vh;overflow:auto}
.instant a{display:flex;gap:12px;align-items:center;padding:10px 12px;border-bottom:1px solid var(--line);color:var(--ink)}
.instant img{width:40px;height:40px;object-fit:contain;background:var(--sunken)}
.instant .all{justify-content:center;color:var(--ai)}
.cur{position:relative}.cur summary{list-style:none;height:44px;display:flex;align-items:center;padding:0 10px;border:1px solid var(--line);border-radius:2px;cursor:pointer;font-family:var(--sans);font-variant-numeric:tabular-nums;font-size:13px}
.cur summary::-webkit-details-marker{display:none}
.cur-list{position:absolute;right:0;top:48px;background:var(--raised);border:1px solid var(--line);display:grid;min-width:90px;z-index:60}
.cur-list a{padding:8px 12px;font-family:var(--sans);font-variant-numeric:tabular-nums;font-size:13px;color:var(--ink)}.cur-list a[aria-current]{color:var(--shu)}
.order-btn{height:44px;display:inline-flex;align-items:center;gap:10px;padding:0 16px;background:var(--gold-grad);color:var(--on-shu);border-radius:2px;font-size:14px;font-weight:700}
.order-btn:hover{color:var(--on-shu);filter:brightness(1.08)}
.badge{font-family:var(--sans);font-variant-numeric:tabular-nums;background:var(--surface);color:var(--ink);padding:0 7px;line-height:20px}
.menu-btn{display:none;width:44px;height:44px;border:1px solid var(--line);border-radius:2px;background:none;color:var(--ink);cursor:pointer;align-items:center;justify-content:center}
@media(max-width:1180px){.search input{width:160px}}
@media(max-width:1020px){
  .menu-btn{display:inline-flex}.search{display:none}
  .nav{display:none;position:fixed;inset:calc(var(--hdr) + 37px) 0 0 0;height:auto;flex-direction:column;background:var(--surface);overflow:auto;padding:8px 16px 40px;z-index:50}
  .nav.open{display:flex}
  .nav-btn{width:100%;justify-content:space-between;height:52px;border-bottom:1px solid var(--line);color:var(--ink)}
  .nav-item:hover .nav-btn{box-shadow:none}
  .panel{position:static;box-shadow:none;border:0;background:none}
  .panel-grid{grid-template-columns:1fr;gap:16px;padding:16px 0}
  .pcol,.feature{grid-column:auto!important}.feature{min-height:0}
  .hdr-in{gap:12px}.logo svg{width:150px}
}
@media(max-width:520px){.cur{display:none}.order-btn{padding:0 12px}}

/* hero */
.hero{display:flex;flex-wrap:wrap;gap:48px 24px;align-items:center;padding-top:88px;padding-bottom:72px}
.hero-copy{flex:1 1 calc(50% - 12px);min-width:300px;display:flex;flex-direction:column;gap:24px}
.hero-art{flex:1 1 calc(50% - 12px);min-width:300px;position:relative;min-height:460px}
.hero-wall{position:absolute;top:0;right:0;width:80%;height:400px;background-color:var(--raised);border:1px solid var(--line);background-image:linear-gradient(45deg,transparent calc(50% - .5px),rgba(20,18,16,.05) calc(50% - .5px),rgba(20,18,16,.05) calc(50% + .5px),transparent calc(50% + .5px)),linear-gradient(-45deg,transparent calc(50% - .5px),rgba(20,18,16,.05) calc(50% - .5px),rgba(20,18,16,.05) calc(50% + .5px),transparent calc(50% + .5px));background-size:48px 48px}
.hero-seal{position:absolute;top:40px;left:0;padding:12px;background:var(--surface)}
.hero-card{position:absolute;left:8%;bottom:0;width:min(380px,88%);background:var(--raised);border:1px solid var(--line);border-radius:4px;box-shadow:0 16px 40px -12px #1412101F;padding:20px;display:flex;flex-direction:column;gap:10px;color:var(--ink)}
.hero-card:hover{color:var(--ink);border-color:var(--line-strong)}
.stats{border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
.stats-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:0 24px}
.stats-grid div{padding:28px 0;display:flex;flex-direction:column;gap:4px}
.stat{font-family:var(--sans);font-variant-numeric:tabular-nums;font-size:34px;line-height:42px;font-weight:500}

/* tiles, set lists, steps, posts */
.tiles{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:24px}
.tile{display:flex;flex-direction:column;gap:10px;padding:24px;min-height:170px;border:1px solid var(--line);background:var(--raised);color:var(--ink)}
.tile:hover{border-color:var(--line-strong);color:var(--ink)}
.tile-title{font-family:var(--display);font-weight:600;font-size:21px;line-height:27px;flex:1}
.setlist{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));column-gap:24px;border-top:1px solid var(--line)}
.setlist a{display:flex;align-items:baseline;gap:16px;padding:14px 0;border-bottom:1px solid var(--line);color:var(--ink);font-weight:500}.setlist a:hover{color:var(--shu)}
.setfilter{max-width:420px;margin:8px 0 8px}
.steps{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:24px}
.steps li{display:flex;flex-direction:column;gap:8px;border-top:1px solid var(--line-strong);padding-top:20px}
.steps strong{font-family:var(--display);font-size:21px;line-height:27px}
.cards3{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:24px}
.post{display:flex;flex-direction:column;gap:12px;padding:28px;background:var(--raised);border:1px solid var(--line);color:var(--ink)}
.post strong{font-size:22px;line-height:28px}.post:hover{color:var(--ink);border-color:var(--line-strong)}
.split{display:flex;flex-wrap:wrap;gap:48px 24px}.split>*{flex:1 1 calc(50% - 12px);min-width:300px}
.split-rule{border-top:2px solid var(--shu);margin-top:88px;padding-top:48px}
.split>div{display:flex;flex-direction:column;gap:16px;align-items:flex-start}
.facts{margin:0;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.4fr);font-size:14px;line-height:20px;border-bottom:1px solid var(--line);align-self:stretch}
.facts dt{padding:11px 16px 11px 0;border-top:1px solid var(--line);color:var(--muted)}
.facts dd{margin:0;padding:11px 0;border-top:1px solid var(--line);font-family:var(--sans);font-variant-numeric:tabular-nums}

/* product cards */
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:24px}
.results .grid{grid-template-columns:repeat(auto-fill,minmax(210px,1fr))}
.card{background:var(--raised);border:1px solid var(--line);border-radius:4px;display:flex;flex-direction:column;overflow:hidden;min-width:0}
.card:hover{border-color:var(--line-strong)}
.well{position:relative;aspect-ratio:1/1;display:grid;place-items:center}
.well img{width:82%;height:82%;object-fit:contain}
.well .tag{position:absolute;top:12px;left:12px}
.card-body{padding:16px;display:flex;flex-direction:column;gap:6px;flex:1}
.card-title{margin:0;font-family:var(--display);font-weight:600;font-size:17px;line-height:23px;flex:1}
.card-title a{color:var(--ink)}.card-title a:hover{color:var(--shu)}
.card .eyebrow{font-size:11px;letter-spacing:.08em;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.price{font-family:var(--sans);font-variant-numeric:tabular-nums;font-size:19px;line-height:26px;font-weight:500}.price small{font-size:12px;color:var(--muted);font-weight:400}
.meta{font-family:var(--sans);font-variant-numeric:tabular-nums;font-size:12px;line-height:18px;color:var(--muted)}.meta b{color:var(--shu);font-weight:500}
.add{display:flex;gap:8px;align-items:stretch;margin-top:8px}
.qty{display:flex;border:1px solid var(--line-strong);border-radius:2px;background:var(--surface);height:36px}
.qty button{width:32px;border:0;background:none;color:var(--ink);cursor:pointer;font-size:18px}
.qty input{width:46px;border:0;border-left:1px solid var(--line);border-right:1px solid var(--line);background:none;text-align:center;font-family:var(--sans);font-variant-numeric:tabular-nums;font-size:14px;-moz-appearance:textfield}
.qty input::-webkit-outer-spin-button,.qty input::-webkit-inner-spin-button{-webkit-appearance:none;margin:0}
.qty-lg{height:52px}.qty-lg button{width:48px}.qty-lg input{width:72px;font-size:17px}
.add .btn-sm{flex:1}

/* listing layout */
.crumbs{display:flex;flex-wrap:wrap;gap:8px;font-size:13px;color:var(--muted);padding:24px 0 8px}.crumbs a{color:var(--muted)}.crumbs a:hover{color:var(--ink)}
.list-head{margin-bottom:16px}.intro{max-width:72ch;color:var(--muted)}
.list-layout{display:grid;grid-template-columns:260px minmax(0,1fr);gap:32px;align-items:start}
.filters{position:sticky;top:calc(var(--hdr) + 16px);max-height:calc(100vh - var(--hdr) - 32px);overflow:auto;padding-right:8px}
.fgroup{border:0;border-top:1px solid var(--line);padding:16px 0;margin:0}
.fgroup legend{padding:0 0 10px;float:left;width:100%}
.fopts{clear:both}.fopts-scroll{max-height:260px;overflow:auto}
.check,.switch{display:flex;align-items:center;gap:10px;padding:4px 0;font-size:14px;cursor:pointer}
.check input,.switch input{width:16px;height:16px;accent-color:var(--shu);flex:none}
.check span:nth-child(2),.switch span:nth-child(2){flex:1}
.count{font-size:12px;color:var(--muted)}
.fsearch{width:100%;height:34px;margin-bottom:8px;padding:0 10px;background:var(--surface);border:1px solid var(--line);border-radius:2px;clear:both}
.range{display:flex;gap:8px;align-items:center;clear:both}.range input{width:100%;height:38px;padding:0 10px;background:var(--surface);border:1px solid var(--line);border-radius:2px;font-family:var(--sans);font-variant-numeric:tabular-nums}
.toolbar{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin-bottom:16px}
.toolbar-right{margin-left:auto;display:flex;flex-wrap:wrap;gap:8px;align-items:center}
.sel select{height:36px;padding:0 8px;background:var(--raised);border:1px solid var(--line-strong);border-radius:2px;color:var(--ink)}
.seg{display:flex;border:1px solid var(--line-strong);border-radius:2px;overflow:hidden}
.seg a{padding:0 12px;line-height:34px;font-size:13px;color:var(--muted)}.seg a[aria-current]{background:var(--ink);color:var(--surface)}
.filters-toggle{display:none}
.chips{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:16px}
.chip{font-size:13px;padding:4px 10px;border:1px solid var(--line-strong);border-radius:2px;color:var(--ink)}.chip-clear{border-color:transparent;color:var(--ai)}
.empty{padding:56px 24px;text-align:center;display:flex;flex-direction:column;align-items:center;gap:12px;border:1px solid var(--line)}
.pager{display:flex;flex-wrap:wrap;gap:6px;justify-content:center;margin:40px 0 0}
.pager a,.pager span{min-width:40px;height:40px;display:inline-grid;place-items:center;padding:0 12px;border:1px solid var(--line);font-family:var(--sans);font-variant-numeric:tabular-nums;font-size:14px;color:var(--ink)}
.pager span[aria-current]{background:var(--shu);border-color:var(--shu);color:var(--on-shu)}
.seo-copy{border-top:1px solid var(--line);margin-top:64px;padding-top:40px}
@media(max-width:900px){
  .list-layout{grid-template-columns:1fr}
  .filters{display:none;position:fixed;inset:0;z-index:70;background:var(--surface);max-height:none;padding:24px 16px}
  .filters.open{display:block}
  .filters-toggle{display:inline-flex}
}

/* list view rows + tables */
.table-wrap{overflow-x:auto;border:1px solid var(--line);border-radius:4px}
.rows{width:100%;border-collapse:collapse;font-size:14px;line-height:20px}
.rows th{text-align:left;font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);font-weight:500;padding:10px 12px;background:var(--sunken);border-bottom:1px solid var(--line)}
.rows td{padding:10px 12px;border-bottom:1px solid var(--line);vertical-align:middle}
.rows tr:last-child td{border-bottom:0}
.rows .num{text-align:right}.rows tfoot td{background:var(--sunken)}
.r-img{width:64px}.r-img img{width:48px;height:48px;object-fit:contain;background:var(--sunken)}
.r-title a{color:var(--ink);font-weight:500}.r-title a:hover{color:var(--shu)}
.r-price{white-space:nowrap;font-size:13px}.r-add{width:200px}
.add-row{margin:0}
.is-out td{opacity:.6}
.x{width:32px;height:32px;border:1px solid var(--line);background:none;color:var(--muted);cursor:pointer;font-size:18px;border-radius:2px}

/* product page */
.pdp{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:56px;align-items:start;padding-top:8px}
.pdp-well{position:relative;aspect-ratio:1/1;display:grid;place-items:center;border:1px solid var(--line)}
.pdp-well img{width:84%;height:84%;object-fit:contain}.pdp-well .tag{position:absolute;top:16px;left:16px}
.pdp-info{display:flex;flex-direction:column;gap:18px}
.pdp-title{margin:0}
.pdp-price{display:flex;flex-wrap:wrap;align-items:baseline;gap:8px 14px;border-top:1px solid var(--line);padding-top:20px}
.big{font-size:36px;line-height:44px;font-weight:500}
.ladder{border-collapse:collapse;width:100%;max-width:380px;font-family:var(--sans);font-variant-numeric:tabular-nums;font-size:14px;line-height:20px}
.ladder caption{text-align:left;font-family:var(--sans);font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);padding-bottom:8px}
.ladder td{padding:8px 12px;border-top:1px solid var(--line)}.ladder tr:last-child td{border-bottom:1px solid var(--line)}
.ladder td:last-child{text-align:right}
.ladder tr.is-active td{background:var(--shu-soft);color:var(--shu);font-weight:500}.ladder tr.is-active td:first-child{box-shadow:inset 2px 0 0 var(--shu)}
.add-pdp{flex-wrap:wrap;align-items:flex-end;gap:16px}.add-pdp>div{display:flex;flex-direction:column;gap:6px}
.add-pdp .btn-lg{flex:1 1 240px}
@media(max-width:860px){.pdp{grid-template-columns:1fr;gap:24px}}

/* prose */
.prose{max-width:72ch;overflow-wrap:break-word}.prose h2{font-family:var(--display);font-size:28px;line-height:36px;margin:40px 0 12px}.prose h3{font-family:var(--display);font-size:21px;margin:28px 0 8px}
.prose p,.prose ul,.prose ol{margin:0 0 16px}.prose li{margin-bottom:6px}.prose img{border:1px solid var(--line)}
.prose table{border-collapse:collapse;width:100%;font-size:14px}.prose th,.prose td{border:1px solid var(--line);padding:8px 10px;text-align:left}
.prose blockquote{margin:0 0 16px;padding-left:16px;border-left:2px solid var(--kin);color:var(--muted)}
.narrow{max-width:760px}.narrow-wide{max-width:1040px}
.article{max-width:760px;padding-bottom:24px}.article-img{margin:8px 0 24px;border:1px solid var(--line)}

/* cart, checkout, quick order */
.cart-foot{display:flex;flex-wrap:wrap;justify-content:space-between;gap:24px;margin-top:24px}
.cart-sum{flex:0 1 380px;display:flex;flex-direction:column;gap:10px}
.checkout{display:grid;grid-template-columns:minmax(0,1fr) 360px;gap:24px;align-items:start}
.co-side{position:sticky;top:calc(var(--hdr) + 16px);display:flex;flex-direction:column;gap:12px}
.co-lines{list-style:none;margin:0;padding:0;font-size:13px;max-height:320px;overflow:auto}
.co-lines li{display:flex;justify-content:space-between;gap:12px;padding:6px 0;border-bottom:1px solid var(--line)}
.fields{display:grid;grid-template-columns:1fr 1fr;gap:14px 16px;clear:both}
.fields label,.notes{display:flex;flex-direction:column;gap:6px;font-size:14px}.span2{grid-column:span 2}
.choice{display:flex;gap:12px;align-items:flex-start;padding:14px;border:1px solid var(--line);border-radius:2px;margin-bottom:10px;cursor:pointer;clear:both}
.choice input{margin-top:5px;accent-color:var(--shu)}.choice>span{display:flex;flex-direction:column;gap:2px;flex:1}
.choice:has(input:checked){border-color:var(--shu)}
.notes{margin-top:8px}
@media(max-width:860px){.checkout{grid-template-columns:1fr}.co-side{position:static}.fields{grid-template-columns:1fr}.span2{grid-column:auto}}
.quick-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-top:24px}
@media(max-width:860px){.quick-grid{grid-template-columns:1fr}}
.quick-results,.quick-matches{display:flex;flex-direction:column;margin-top:12px}
.qrow{display:grid;grid-template-columns:44px minmax(0,1fr) auto;gap:12px;align-items:center;padding:10px 0;border-bottom:1px solid var(--line)}
.qrow img{width:44px;height:44px;object-fit:contain;background:var(--sunken)}
.qrow .add{margin:0}
.example{background:var(--sunken);padding:12px;border:1px solid var(--line);white-space:pre-wrap}
.btc{word-break:break-all;background:var(--sunken);padding:12px;border:1px solid var(--line)}

/* drawer + toast */
.drawer{position:fixed;top:0;right:0;bottom:0;width:min(420px,100vw);background:var(--raised);border-left:1px solid var(--line);z-index:80;display:flex;flex-direction:column;box-shadow:0 16px 40px -12px #1412101F}
.drawer-head{display:flex;justify-content:space-between;align-items:center;padding:16px;border-bottom:1px solid var(--line)}
.drawer-body{flex:1;overflow:auto;padding:0 16px}
.drawer-foot{padding:16px;border-top:1px solid var(--line);display:flex;flex-direction:column;gap:10px}
.dline{display:grid;grid-template-columns:48px minmax(0,1fr) auto;gap:12px;padding:12px 0;border-bottom:1px solid var(--line);font-size:14px;line-height:20px}
.dline img{width:48px;height:48px;object-fit:contain;background:var(--sunken)}
.toast{position:fixed;left:50%;bottom:24px;transform:translateX(-50%);background:var(--ink);color:var(--surface);padding:12px 18px;border-radius:2px;z-index:90;font-size:14px;max-width:calc(100vw - 32px)}

/* footer */
.ftr{border-top:1px solid var(--line);margin-top:112px}
.ftr-grid{display:flex;flex-wrap:wrap;gap:40px 24px;padding-top:64px;padding-bottom:40px}
.ftr-brand{flex:1 1 300px;display:flex;flex-direction:column;gap:14px;color:var(--ink)}
.ftr-brand p{margin:0;font-size:14px;line-height:22px;max-width:36ch}
.ftr-col{flex:1 1 150px;display:flex;flex-direction:column;gap:10px;font-size:14px}
.ftr-col .eyebrow{padding-bottom:8px;border-bottom:1px solid var(--line)}
.ftr-col a{color:var(--ink)}.ftr-col a:hover{color:var(--shu)}
.ftr-legal{display:flex;flex-wrap:wrap;gap:12px 24px;padding-top:24px;padding-bottom:40px;border-top:1px solid var(--line);font-size:12px;line-height:18px;color:var(--muted)}
.ftr-legal span:first-child{flex:1 1 640px}

/* polish */
.narrow-wide{padding-top:32px}
.filters-close{margin-bottom:16px}
@media(min-width:901px){.filters-close{display:none}}
@media(max-width:600px){
  .grid,.results .grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
  .card-body{padding:12px}.card-title{font-size:15px;line-height:20px}.price{font-size:16px}
  .add{flex-wrap:wrap}.add .qty{width:100%}.add .qty input{flex:1}.add .btn-sm{width:100%}
  .toolbar-right{margin-left:0;width:100%}.sel{flex:1}.sel select{width:100%}
  .hero{padding-top:48px}.hero-art{min-height:380px}.hero-wall{height:320px}
  .r-add{width:auto}
}
/* set card list */
.cardlist .table-wrap{max-height:none}
.cl-table{width:100%;border-collapse:collapse;font-size:14px}
.cl-table th{text-align:left;font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted);font-weight:500;padding:9px 12px;background:var(--sunken);border-bottom:1px solid var(--line);position:sticky;top:0}
.cl-table td{padding:8px 12px;border-bottom:1px solid var(--line);vertical-align:middle}
.cl-table tr:last-child td{border-bottom:0}
.cl-table td a{color:var(--ink);text-decoration:none}.cl-table td a:hover{color:var(--shu);text-decoration:underline}
.cl-table .num{text-align:right;white-space:nowrap}.cl-table td:first-child{white-space:nowrap;color:var(--muted)}
.cl-table .ok{color:var(--matcha)}
@media (max-width:640px){.cl-table th:nth-child(3),.cl-table td:nth-child(3){display:none}.cl-table td,.cl-table th{padding:8px}}

/* gold detailing */
.hdr{border-bottom:1px solid var(--line)}
.display,.h1{color:var(--ink)}
@supports not (background-clip:text){.display,.h1{color:var(--ink)}}
.tag-soldout{background:var(--danger-soft);color:var(--danger)}
.ftr{border-top:1px solid #E7E2D9}
.lang-tag{display:inline-block;font:500 10px/16px var(--sans);letter-spacing:.06em;padding:0 5px;border:1px solid var(--line-strong);border-radius:2px;color:var(--muted);margin-left:6px;vertical-align:1px}
/* homepage popular links + featured set banner */
.chips.popular{margin-top:24px;align-items:center}
.chips.popular .eyebrow{margin-right:8px}
.banner{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:40px;border:1px solid var(--line-strong);background:var(--raised);color:var(--ink)}
.banner .h2{margin:8px 0}.banner p{margin:0;max-width:60ch}
.banner:hover{color:var(--ink);border-color:var(--shu)}
@media(max-width:720px){.banner{flex-direction:column;align-items:flex-start;padding:24px}}
/* order page: Bitcoin payment */
.btc-pay{display:flex;gap:24px;align-items:flex-start;flex-wrap:wrap}
.btc-qr{width:184px;height:184px;padding:8px;background:#FFFFFF;border:1px solid var(--line);flex:none}
.btc-qr img,.btc-qr canvas{display:block}
.btc-pay .big{font-size:24px;line-height:32px;color:var(--shu);margin:4px 0}
.btc{word-break:break-all}
/* customer reviews */
.reviews-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:16px}
.review{margin:0;display:flex;flex-direction:column;gap:10px;padding:20px;border:1px solid var(--line);background:var(--raised)}
.review blockquote{margin:0;color:var(--ink);font-size:15px;line-height:24px}
.review-title{font-family:var(--display);font-size:18px;line-height:26px}
.review figcaption{display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap;color:var(--muted);font-size:14px;margin-top:auto}
.review-photo img{display:block;width:100%;height:200px;object-fit:cover;border:1px solid var(--line)}
.stars{color:var(--shu);letter-spacing:2px;font-size:16px}.stars .off{color:var(--line-strong)}
/* mobile polish: compact stats and category tiles */
@media(max-width:640px){
  .stats-grid{grid-template-columns:1fr 1fr;gap:0 16px}
  .stats-grid div{padding:18px 0}
  .stat{font-size:24px;line-height:32px}
  .tiles{grid-template-columns:1fr 1fr;gap:12px}
  .tile{min-height:0;padding:16px;gap:6px}
  .tile-title{font-size:16px;line-height:22px}
}
.prose table{margin:8px 0 24px}

/* ================================================================ sharpened design (Oct 2026)
   One bold thing: the fanned chase cards in gold-leaf frames. Everything else stays quiet:
   sentence-case labels, tabular figures instead of a typewriter face, gold used for links and actions only. */
.mono{font-family:var(--sans);font-variant-numeric:tabular-nums;letter-spacing:0}
.btc,code,.sku{font-family:var(--mono)}
.price,.stat,.ladder td,.cl-table td{font-variant-numeric:tabular-nums}
.eyebrow{text-transform:none;letter-spacing:.01em;font-size:13px;line-height:18px}
.card .eyebrow{font-size:12px;letter-spacing:0}
.sec-head a{color:var(--ai)}.sec-head a:hover{color:#8F3807;text-decoration:underline;text-underline-offset:3px}

/* hero */
.hero{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);gap:48px;align-items:center;padding-top:72px;padding-bottom:64px}
.hero-copy{gap:22px;min-width:0}
.hero .display{max-width:13ch;font-size:clamp(40px,5.2vw,72px)}
.hero .lead{max-width:46ch;color:var(--muted)}
.hero-search{display:flex;gap:8px;max-width:520px}
.hero-search input{flex:1;min-width:0;height:52px;padding:0 16px;background:var(--raised);border:1px solid var(--line-strong);color:var(--ink);font-size:16px}
.hero-search input:focus{outline:none;border-color:var(--shu);box-shadow:var(--focus)}
.hero-search .btn{height:52px;padding:0 24px}
.hero-quick{display:flex;flex-wrap:wrap;gap:6px 14px;font-size:15px}
.hero-quick a{color:var(--ink);border-bottom:1px solid var(--line-strong)}.hero-quick a:hover{color:var(--shu);border-color:var(--shu)}
.hero-facts{display:flex;flex-wrap:wrap;gap:6px 0;margin:6px 0 0;color:var(--muted);font-size:14px}
.hero-facts span+span::before{content:"";display:inline-block;width:4px;height:4px;margin:0 12px 3px;background:var(--shu);transform:rotate(45deg)}
.fan{position:relative;height:500px;max-width:560px;justify-self:center;width:100%}
.fan-card{position:absolute;top:10px;left:50%;width:236px;margin-left:-118px;color:var(--ink);transform-origin:50% 115%;transition:transform .3s ease}
.fan-frame{display:block;padding:6px;border-radius:14px;background:linear-gradient(140deg,#F59A55 0%,#E8681A 38%,#B54709 70%,#F2843D 100%);box-shadow:0 28px 50px -24px #14121066,0 0 0 1px #14121033}
.fan-frame img{display:block;width:100%;aspect-ratio:63/88;object-fit:cover;border-radius:9px;background:var(--raised)}
.fan-label{display:flex;justify-content:space-between;gap:10px;margin-top:12px;font-size:14px;line-height:20px}
.fan-name{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.fan-price{color:var(--shu);font-variant-numeric:tabular-nums;font-weight:500}
.fan-0{z-index:3;transform:translateY(0)}
.fan-1{z-index:2;transform:translateX(-62%) rotate(-11deg) scale(.9)}
.fan-2{z-index:1;transform:translateX(62%) rotate(11deg) scale(.9)}
.fan-0:hover{transform:translateY(-14px)}
.fan-1:hover{transform:translateX(-66%) translateY(-14px) rotate(-11deg) scale(.9);z-index:4}
.fan-2:hover{transform:translateX(66%) translateY(-14px) rotate(11deg) scale(.9);z-index:4}
@keyframes fan-l{from{transform:none}}@keyframes fan-r{from{transform:none}}
.fan-1{animation:fan-l .7s cubic-bezier(.2,.8,.2,1) .15s both}.fan-2{animation:fan-r .7s cubic-bezier(.2,.8,.2,1) .15s both}
@media (prefers-reduced-motion:reduce){.fan-1,.fan-2{animation:none}.fan-card{transition:none}}
@media(max-width:900px){.hero{grid-template-columns:1fr;padding-top:40px}.fan{height:400px}.fan-card{width:190px;margin-left:-95px}}
@media(max-width:480px){.fan{height:330px}.fan-card{width:150px;margin-left:-75px}.fan-1{transform:translateX(-58%) rotate(-10deg) scale(.88)}.fan-2{transform:translateX(58%) rotate(10deg) scale(.88)}.fan-label{font-size:12px}}

/* category tiles: title first, count second */
.tile{justify-content:space-between;min-height:120px}
.tile-title{font-family:var(--display);font-weight:600;font-size:20px;line-height:26px}
.tile-n{color:var(--muted);font-size:13px;font-variant-numeric:tabular-nums}
.tile:hover{border-color:var(--shu);color:var(--ink)}

/* shop by PokÃ©mon: a typographic index of names */
.names{display:flex;flex-wrap:wrap;gap:4px 28px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:20px 0}
.names a{font-family:var(--display);font-weight:600;font-size:clamp(22px,2.6vw,34px);line-height:1.35;color:var(--ink)}
.names a:hover{color:var(--shu)}
.names sup{font-family:var(--sans);font-weight:400;font-size:12px;color:var(--muted);margin-left:4px;vertical-align:super;font-variant-numeric:tabular-nums}
.names-more{margin-top:14px}

/* featured set banner with its set code as the anchor */
.banner{border-color:var(--line)}
.banner-code{font-family:var(--display);font-weight:600;font-size:56px;line-height:1;color:var(--shu);min-width:120px}
@media(max-width:720px){.banner-code{font-size:40px}}

/* set and game lists */
.set-series{display:block;color:var(--muted);font-size:13px;font-weight:400}

/* guides grouped by topic */
.topics{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:32px}
.topics .h3{padding-bottom:10px;border-bottom:1px solid var(--line-strong);margin-bottom:8px}
.topics ul,.explore ul,.link-grid{list-style:none;margin:0;padding:0}
.topics li a,.explore li a{display:block;padding:7px 0;color:var(--ink);border-bottom:1px solid var(--line)}
.topics li a:hover,.explore li a:hover{color:var(--shu)}

/* ordering steps, numbered in Japanese because they are a sequence */
.step-n{font-family:var(--display);font-weight:600;font-size:40px;line-height:1;color:var(--shu)}
.steps{margin-top:24px}

/* related pages under a listing heading */
.related{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-top:16px}
.related a{font-size:14px;padding:5px 12px;border:1px solid var(--line-strong);border-radius:999px;color:var(--ink)}
.related a:hover{border-color:var(--shu);color:var(--shu)}

/* product page: keep exploring */
.explore-cols{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:32px;margin-top:20px}
.explore .h3{font-size:18px;color:var(--muted);font-family:var(--sans);font-weight:500}

/* guides: contents and keep reading */
.article-layout{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:56px;align-items:start}
.byline{margin:-6px 0 20px}
.toc{position:sticky;top:110px;border-left:1px solid var(--line-strong);padding-left:20px}
.toc-title{font-weight:500;margin:0 0 8px}
.toc ol{margin:0;padding-left:18px;color:var(--muted)}
.toc li{margin:6px 0;font-size:14px;line-height:20px}.toc a{color:var(--muted)}.toc a:hover{color:var(--shu)}
.prose h2[id]{scroll-margin-top:110px}
@media(max-width:980px){.article-layout{grid-template-columns:minmax(0,1fr)}.toc{position:static;order:-1;border-left:0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:16px 0}}
.link-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:0 24px;margin-top:16px;border-top:1px solid var(--line)}
.link-grid a{display:block;padding:12px 0;border-bottom:1px solid var(--line);color:var(--ink);font-family:var(--display);font-weight:600;font-size:18px}
.link-grid a:hover{color:var(--shu)}

/* fan: name and price sit on a plate inside each card so the fanned labels never collide */
.fan-card{display:block}
.fan-frame{position:relative}
.fan-label{position:absolute;left:6px;right:6px;bottom:6px;margin:0;padding:22px 12px 10px;border-radius:0 0 9px 9px;background:linear-gradient(transparent,#1412101F 45%);flex-direction:column;gap:0}
.fan-name{font-weight:500}
.fan-price{font-size:16px}
.price{font-size:20px}
@media(max-width:640px){.hero-facts{flex-direction:column;gap:4px}.hero-facts span::before{content:"";display:inline-block;width:4px;height:4px;margin:0 10px 3px 0;background:var(--shu);transform:rotate(45deg)}.hero-facts span+span::before{margin:0 10px 3px 0}}
/* logo: gold ãƒ card + wordmark */
.logo{align-items:center;gap:10px}
.logo-word{font-family:var(--display);font-weight:700;font-size:25px;line-height:1;letter-spacing:.015em;color:var(--ink)}
.logo:hover .logo-word{color:#000}
.ftr-brand .logo-word{font-size:24px}
.ftr-brand > svg{vertical-align:middle;margin-right:8px}
@media(max-width:480px){.logo-word{font-size:21px}.logo-mark{width:22px;height:30px}}
.logo svg.logo-mark{width:27px;height:36px}
@media(max-width:480px){.logo svg.logo-mark{width:22px;height:30px}}

/* hero showcase: the featured set, its box, what to buy, and its chase cards */
.showcase{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,1fr);grid-template-areas:"main info" "chase chase";gap:0;border:1px solid var(--line-strong);background:var(--raised);position:relative}
.showcase::before{content:"";position:absolute;inset:-1px;border:1px solid transparent;background:linear-gradient(140deg,#F59A55,#E8681A 35%,transparent 60%,#B54709) border-box;-webkit-mask:linear-gradient(#000 0 0) padding-box,linear-gradient(#000 0 0);-webkit-mask-composite:xor;mask-composite:exclude;pointer-events:none}
.sc-main{grid-area:main;position:relative;display:grid;place-items:center;padding:28px;background:radial-gradient(70% 70% at 50% 45%,#FDF1E7 0%,var(--raised) 70%);min-height:300px}
.sc-main img{width:100%;max-width:360px;height:auto;aspect-ratio:1;object-fit:contain;filter:drop-shadow(0 18px 24px #14121026)}
.sc-new{position:absolute;top:16px;left:16px;font-size:13px;font-weight:500;color:var(--on-shu);background:var(--gold-grad);padding:3px 10px}
.sc-info{grid-area:info;display:flex;flex-direction:column;gap:12px;padding:28px 28px 24px 8px;justify-content:center}
.sc-title{font-family:var(--display);font-weight:700;font-size:clamp(26px,2.4vw,34px);line-height:1.15;margin:0}
.sc-title a{color:var(--ink)}.sc-title a:hover{color:var(--shu)}
.sc-sub{margin:-6px 0 4px;font-size:14px}
.sc-buy{list-style:none;margin:0 0 8px;padding:0;border-top:1px solid var(--line)}
.sc-buy a{display:flex;justify-content:space-between;gap:12px;padding:10px 0;border-bottom:1px solid var(--line);color:var(--ink);font-size:14px;line-height:20px}
.sc-buy a:hover{color:var(--shu)}
.sc-price{color:var(--shu);white-space:nowrap;font-variant-numeric:tabular-nums}
.sc-info .btn{align-self:flex-start}
.sc-chase{grid-area:chase;border-top:1px solid var(--line);padding:18px 24px 22px}
.sc-chase-title{margin:0 0 12px;font-size:14px;color:var(--muted)}
.sc-cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}
.sc-cards a{display:flex;flex-direction:column;gap:4px;color:var(--ink);font-size:12px;line-height:16px;min-width:0}
.sc-cards img{width:100%;aspect-ratio:63/88;object-fit:cover;border-radius:6px;border:1px solid var(--line-strong);background:var(--surface);transition:transform .2s ease}
.sc-cards a:hover img{transform:translateY(-4px);border-color:var(--shu)}
.sc-cards span:first-of-type{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
@media (prefers-reduced-motion:reduce){.sc-cards img{transition:none}}
@media(max-width:1100px){.showcase{grid-template-columns:1fr;grid-template-areas:"main" "info" "chase"}.sc-info{padding:4px 24px 24px}.sc-main{min-height:0}}
@media(max-width:480px){.sc-cards{gap:8px}.sc-chase{padding:16px}}
/* product photos often come on white: show the featured box on an ivory plinth so the photo blends in */
.sc-main{background:radial-gradient(80% 80% at 50% 40%,#FFFFFF 0%,#FAF8F4 62%,#EFEAE1 100%)}
.sc-main img{mix-blend-mode:multiply;filter:none;max-width:340px}
.sc-new{box-shadow:0 2px 8px #1412102e}
.sc-info{padding:28px 28px 24px 28px}
@media(max-width:1100px){.sc-info{padding:20px 24px 24px}}
.showcase{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}.sc-buy a span:first-child{min-width:0}
.sc-main{padding:44px 16px 20px}.sc-main img{max-width:100%;width:100%}
/* showcase: just the featured photo, the set name and one button */
.showcase{grid-template-columns:minmax(0,1.25fr) minmax(0,1fr);grid-template-areas:"main info"}
.sc-main{min-height:420px;padding:48px 20px 24px}
.sc-info{gap:16px}
.sc-info .btn{margin-top:8px}
@media(max-width:1100px){.showcase{grid-template-columns:1fr;grid-template-areas:"main" "info"}.sc-main{min-height:0}}

/* ================================================================ Toramori identity
   Clean white, confident black type, one tiger-orange for actions and highlights. */
.display,.h1,.h2,.h3,.tile-title,.sc-title,.names a,.link-grid a,.mincho,.steps strong,.card-title,.pdp-title{font-family:var(--display);font-weight:800;letter-spacing:-.015em}
.display{font-size:clamp(40px,5vw,70px);line-height:1.02;font-stretch:92%}
.h1{font-weight:800}
.card-title{font-weight:700;letter-spacing:-.005em}
a{color:var(--ai)}a:hover{color:#8F3807}
.btn{border-color:var(--line-strong);color:var(--ink)}
.btn:hover{border-color:var(--ink)}
.btn-primary{background:var(--shu);border-color:var(--shu);color:#141210}.btn-primary:hover{background:#D9590C;border-color:#D9590C;filter:none;color:#141210}
.hdr{background:#FFFFFFF2;backdrop-filter:saturate(1.4) blur(10px);border-bottom:1px solid var(--line)}
.bar{background:#141210;color:#F2EEE7}.bar a{color:#F59A55}
.tag-stock{background:var(--matcha-soft);color:var(--matcha)}
.card{background:#fff;border-color:var(--line)}
.card:hover{border-color:var(--line-strong);box-shadow:0 10px 24px -16px #14121040}
.well{background-color:#FAF8F4}
.price{color:var(--ink)}
.meta b{color:var(--ai)}
.stars{color:#E8681A}
.step-n{color:var(--shu);font-family:"Zen Kaku Gothic New",sans-serif;font-weight:700}
.sc-new{background:#141210;color:#fff;box-shadow:none}
.showcase{background:#fff;border-color:var(--line)}
.showcase::before{background:linear-gradient(140deg,#F59A55,#E8681A 35%,transparent 60%,#141210) border-box}
.banner-code{color:var(--shu)}
.ftr{background:#141210;color:#E9E4DB;border-top:0}
.ftr a{color:#E9E4DB}.ftr a:hover{color:#F59A55}
.ftr .muted,.ftr-legal{color:#A9A196}
.ftr-col .eyebrow{color:#F59A55;border-color:#3A342C}
.ftr-legal{border-top-color:#3A342C}
.ftr .logo-word{color:#fff}
.chip,.related a{background:#fff}
.names a:hover,.topics li a:hover,.explore li a:hover,.setlist a:hover{color:var(--ai)}
.fan-frame{background:linear-gradient(140deg,#F59A55 0%,#E8681A 40%,#B54709 75%,#F2843D 100%)}
.sc-main{background:radial-gradient(80% 80% at 50% 40%,#FFFFFF 0%,#FAF7F2 62%,#F1ECE3 100%)}
.cl-table th{background:var(--sunken)}
.toast{background:#141210;color:#fff}
/* ---------- Toramori mega menus */
.logo{align-items:center;gap:10px}.logo-mark{flex:none;border-radius:9px}
.logo-word{font-family:var(--display);font-weight:900;font-size:24px;letter-spacing:-.03em;color:var(--ink)}
.nav-btn{color:#3A342C;font-weight:600}
.nav-btn svg{transition:transform .18s ease}
.nav-btn[aria-expanded="true"] svg{transform:rotate(180deg)}
.nav-item:hover .nav-btn,.nav-btn[aria-expanded="true"]{color:var(--ink);box-shadow:inset 0 -3px 0 var(--shu)}
.panel{background:#fff;border-top:1px solid var(--line);box-shadow:0 28px 60px -24px #14121038}
.panel:not([hidden]){animation:panelIn .18s ease-out}
@keyframes panelIn{from{opacity:0;transform:translateY(-6px)}to{opacity:1;transform:none}}
.panel-grid{gap:28px;padding-top:28px;padding-bottom:28px}
.pcol-title{margin:0 0 8px;padding-bottom:10px;border-bottom:2px solid var(--ink);font-family:var(--display);font-weight:800;font-size:13px;letter-spacing:.06em;text-transform:uppercase;color:var(--ink)}
.pcol a{justify-content:space-between;padding:7px 8px;margin:0 -8px;border-radius:6px;font-size:15px;transition:background .12s,color .12s}
.pcol a:hover{background:#FDF0E6;color:var(--ai)}
.pcol .pl{display:flex;align-items:baseline;gap:8px;min-width:0}
.pcol .code{min-width:0;font-size:11px;padding:0 5px;border:1px solid var(--line);border-radius:4px;line-height:16px}
.pcol .cnt{font-size:12px;font-variant-numeric:tabular-nums;color:#9A9186;flex:none}
.pcol a:hover .cnt{color:var(--ai)}
.pcol .note{flex:none;font-size:10px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:#fff;background:var(--shu);padding:1px 6px;border-radius:4px}
.feature{position:relative;justify-content:flex-start;gap:0;min-height:0;padding:0;border:0;border-radius:12px;overflow:hidden;background:#141210;color:#fff;transition:transform .18s,box-shadow .18s}
.feature:hover{color:#fff;transform:translateY(-2px);box-shadow:0 18px 36px -18px #E8681A99}
.feature-img{display:flex;align-items:center;justify-content:center;height:190px;background:radial-gradient(70% 80% at 50% 40%,#fff 0%,#F6F1EA 100%)}
.feature-img img{max-height:170px;max-width:88%;object-fit:contain;mix-blend-mode:multiply;transition:transform .25s}
.feature:hover .feature-img img{transform:scale(1.04)}
.feature-txt{display:flex;flex-direction:column;gap:6px;padding:18px 20px 20px}
.feature:not(.has-img) .feature-txt{padding:28px 24px;min-height:100%;justify-content:flex-end;background:linear-gradient(150deg,#141210 55%,#3A1C08)}
.feature-kicker{align-self:flex-start;font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:#141210;background:var(--shu);padding:2px 8px;border-radius:4px}
.feature strong{font-size:21px;line-height:26px;color:#fff}
.feature .muted{color:#BDB5AA}
.feature-cta{margin-top:6px;font-weight:700;color:#F59A55}.feature-cta::after{content:" â†’";transition:margin .15s}
.feature:hover .feature-cta::after{margin-left:4px}
.panel-foot{border-top:1px solid var(--line);background:#FAF8F4}
.panel-foot a{display:inline-block;padding:12px 0;font-weight:700;color:var(--ink)}.panel-foot a::after{content:" â†’";color:var(--shu)}
.panel-foot a:hover{color:var(--ai)}
@media(max-width:1020px){
  .logo svg{width:32px}.logo-word{font-size:21px}
  .panel{animation:none!important;border-top:0}
  .feature-img{height:150px}.panel-foot{background:none;border:0}.panel-foot .wrap{padding:0}
  .nav-btn[aria-expanded="true"]{box-shadow:none;color:var(--ai)}
}
@media(max-width:1020px){
  .hdr{backdrop-filter:none;-webkit-backdrop-filter:none;background:#fff}
  .nav{inset:auto 0 0 0;top:calc(var(--hdr) + 37px);background:#fff;box-shadow:0 -1px 0 var(--line)}
