  document.addEventListener('click', e => { if (desktop() && !e.target.closest('[data-menu]')) closeAll(); });
  const mb = $('[data-mobile-menu]');
  if (mb) mb.addEventListener('click', () => { const nav = $('.nav'); const on = nav.classList.toggle('open'); if (on) { window.scrollTo(0, 0); nav.style.top = Math.round($('.hdr').getBoundingClientRect().bottom) + 'px'; } mb.setAttribute('aria-expanded', on); document.body.style.overflow = on ? 'hidden' : ''; });

  /* ---------- quantity steppers */
  function clampQty(form, v) {
    const step = +form.dataset.step || 1, moq = +form.dataset.moq || 1, min = form.hasAttribute('data-set') ? 0 : moq;
    v = Math.max(min, Math.round(v) || 0);
    if (v > 0 && v < moq) v = moq;
    if (v > moq && (v - moq) % step) v += step - ((v - moq) % step);
    return v;
  }
